export type ThinkingLevel = "off" | "low" | "medium" | "high";

export type CompactionReason = "automatic" | "manual" | "provider_overflow";

export type BudgetUnit = "micros_usd" | "ai_credit_micros" | "tokens";

export type BudgetLevel = "warning" | "spend_rate_alarm" | "hard_cap";

export type BudgetScope = "session" | "daily" | "trailing_minute";

export type Usage = { input_tokens: string, output_tokens: string, cache_read_tokens: string, cache_write_tokens: string, reasoning_tokens: string, };

export type Cost = { "kind": "monetary", amount_micros: string, currency: string, } | { "kind": "ai_credits", credits_micros: string, nominal_amount_micros?: string | null, currency?: string | null, } | { "kind": "subscription_quota", used?: string | null, unit?: string | null, } | { "kind": "unavailable", reason: string, };

export type UnrestorablePath = { path: string, reason: string, };

export type EngineErrorCategory = "provider" | "tool" | "sandbox" | "config" | "extension" | "protocol" | "internal";

export type EngineError = { category: EngineErrorCategory, code: string, message: string, retryable: boolean, details?: JsonValue | null, };

export type CommandOutcome = { "type": "accepted", } | { "type": "rejected", error: EngineError, };

